    "text": "{\n    \"name\": \"arcade-character-animations\",\n    \"version\": \"0.1.0\",\n    \"description\": \"\",\n    \"dependencies\": {\n        \"device\": \"*\"\n    },\n    \"files\": [\n        \"main.ts\",\n        \"README.md\",\n        \"docs/clear-character-state.md\",\n        \"docs/loop-character-animation.md\",\n        \"docs/matches-rule.md\",\n        \"docs/predicate.md\",\n        \"docs/run-character-animation.md\",\n        \"docs/set-character-animations-enabled.md\",\n        \"docs/set-character-state.md\",\n        \"docs/rule.md\",\n        \"docs/set-controller.md\",\n        \"docs/lock-facing-direction.md\",\n        \"docs/facing-direction.md\",\n        \"docs/unlock-facing-direction.md\"\n    ],\n    \"testFiles\": [\n        \"test.ts\"\n    ],\n    \"targetVersions\": {\n        \"target\": \"1.4.44\",\n        \"targetId\": \"arcade\"\n    },\n    \"supportedTargets\": [\n        \"arcade\"\n    ],\n    \"preferredEditor\": \"tsprj\"\n}\n",
